#include <string>
#include <sstream>
#include <unordered_map>
using namespace std;

class Solution {
public:
    string convertWordsToDigits(string s) {
        unordered_map<string, string> word_map = {
            {"zero", "0"}, {"one", "1"}, {"two", "2"}, {"three", "3"}, {"four", "4"},
            {"five", "5"}, {"six", "6"}, {"seven", "7"}, {"eight", "8"}, {"nine", "9"}
        };
        stringstream ss(s);
        string word;
        string res = "";
        while (ss >> word) {
            if (word_map.count(word)) {
                res += word_map[word];
            }
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public String convertWordsToDigits(String s) {
        Map<String, String> wordMap = Map.of(
            "zero", "0", "one", "1", "two", "2", "three", "3", "four", "4",
            "five", "5", "six", "6", "seven", "7", "eight", "8", "nine", "9"
        );
        StringBuilder sb = new StringBuilder();
        for (String w : s.split("\\s+")) {
            if (wordMap.containsKey(w)) {
                sb.append(wordMap.get(w));
            }
        }
        return sb.toString();
    }
}

var convertWordsToDigits = function(s) {
    const wordMap = {
        "zero": "0", "one": "1", "two": "2", "three": "3", "four": "4",
        "five": "5", "six": "6", "seven": "7", "eight": "8", "nine": "9"
    };
    return s.split(/\s+/).map(w => wordMap[w] || "").join("");
};
